const configuredTax = 30;
// END GENERATED CATALOG
const catalogByMaterial = new Map(configuredCatalog.map(i => [i.material, i]));
const featuredMaterials = new Set();
const items = demoItems.map(demo => { if(demo.category === 'Custom') return demo; const material = itemTextures[demo.id]; featuredMaterials.add(material); return {...demo, ...catalogByMaterial.get(material), id:demo.id}; }).concat(configuredCatalog.filter(i => !featuredMaterials.has(i.material)));
let visibleLimit = 48;
const watchlistStorageKey='dynamicshop.watchlist.v1';
function readWatchlist(){
  try{
    const saved=JSON.parse(localStorage.getItem(watchlistStorageKey)||'[]');
    const validIds=new Set(items.map(item=>item.id));
    return new Set(Array.isArray(saved)?saved.filter(id=>typeof id==='string'&&validIds.has(id)):[]);
  }catch{return new Set()}
}
function saveWatchlist(){
  try{localStorage.setItem(watchlistStorageKey,JSON.stringify([...watched]));return true}
  catch{return false}
}
let category='All',page='catalog',selected=null,watched=readWatchlist(),toastTimer;
const $=id=>document.getElementById(id),money=n=>n == null ? 'Unavailable' : '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
$('heroGem').innerHTML=art('emerald');
function notify(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2700)}
function stockText(item){return item.disabled?'Trading disabled':item.stock==null?'Stock shown in game':item.stock<=0?'Out of stock':item.stock.toLocaleString()+' in stock'}
function render(){
  const search=$('search').value.toLowerCase().replaceAll('_',' ').trim();
  let visible=items.filter(i=>(category==='All'||i.category===category)&&i.name.toLowerCase().includes(search)&&(page!=='favorites'||watched.has(i.id))&&(!$('hideOutOfStock').checked||i.stock==null||i.stock>0));
  const sort=$('sort').value;
  if(sort==='low'||sort==='high') visible.sort((a,b)=>!!a.disabled!==!!b.disabled?(a.disabled?1:-1):sort==='low'?a.buy-b.buy:b.buy-a.buy);
  if(sort==='name') visible.sort((a,b)=>a.name.localeCompare(b.name));
  $('resultCount').textContent=visible.length.toLocaleString()+' '+(visible.length===1?'item':'items');
  $('watchCount').textContent=watched.size;
  $('empty').hidden=visible.length>0;
  $('emptyText').textContent=page==='favorites'&&!watched.size?'Tap the heart on an item to keep it close.':'Try another name or category.';
  const shown=visible.slice(0,visibleLimit);
  $('itemGrid').innerHTML=shown.map(i=>`<article class="item-card ${i.disabled?'unavailable':''}"><button class="watch-button ${watched.has(i.id)?'active':''}" data-watch="${i.id}" aria-label="${watched.has(i.id)?'Remove':'Add'} ${escapeText(i.name)} ${watched.has(i.id)?'from':'to'} watchlist" aria-pressed="${watched.has(i.id)}">${icon('heart')}</button><button class="card-open" data-open="${i.id}" aria-label="View ${escapeText(i.name)}"><div class="card-art" style="--tint:${i.tint}">${i.disabled?'<span class="tag disabled-tag">UNAVAILABLE</span>':i.tag?`<span class="tag ${i.category==='Custom'?'custom':''}">${i.tag}</span>`:''}${art(i.id)}</div><div class="card-info"><span class="card-category">${escapeText(i.category)}</span><h3>${escapeText(i.name)}</h3><div class="card-prices"><div><span class="price-label">BUY</span><strong>${money(i.buy)}</strong></div><div><span class="price-label">SELL</span><strong>${money(i.sell)}</strong></div></div></div><div class="card-bottom"><span>${i.stock>0&&!i.disabled?'<i class="green-dot"></i>':''}${stockText(i)}</span><span>View item ↗</span></div></button></article>`).join('');
  $('loadMore').hidden=shown.length>=visible.length;
  $('catalogProgress').textContent=visible.length?'Showing '+shown.length+' of '+visible.length.toLocaleString()+' items':'';
  document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openItem(b.dataset.open));
  document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>toggleWatch(b.dataset.watch));
}
function toggleWatch(id){watched.has(id)?watched.delete(id):watched.add(id);const saved=saveWatchlist();render();if(selected)updateWatchButton();notify((watched.has(id)?'Added to your watchlist':'Removed from your watchlist')+(saved?'':' · browser storage unavailable; change lasts for this visit'))}
function updateWatchButton(){$('watchItem').textContent=watched.has(selected.id)?'Remove from watchlist':'Add to watchlist'}
