function renderItemTransactions(type='All', limit=5) {
  const itemTrades=trades.filter(trade=>trade[0]===selected.id);
  const filtered=itemTrades.filter(trade=>type==='All'||trade[2]===type);
  $('itemTradeCount').textContent=itemTrades.length+' '+(itemTrades.length===1?'trade':'trades');
  document.querySelectorAll('[data-item-trade-type]').forEach(button=>{
    const active=button.dataset.itemTradeType===type;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
    button.onclick=()=>renderItemTransactions(button.dataset.itemTradeType);
  });
  $('itemTransactionList').innerHTML=filtered.length?filtered.slice(0,limit).map(trade=>{
    const [,player,type,quantity,time]=trade;
    const unitPrice=type==='BUY'?selected.buy:selected.sell;
    return `<div class="item-trade-row"><span class="trade-avatar" aria-hidden="true">${player[0]}</span><div class="trade-person"><strong>${player}</strong><time>${time}</time></div><span class="tx-type ${type==='SELL'?'sell':''}">${type==='BUY'?'Buy':'Sell'}</span><div class="trade-amount"><strong>${money(unitPrice*quantity)}</strong><span>${quantity} × ${money(unitPrice)}</span></div></div>`;
  }).join(''):`<div class="item-trades-empty">${itemTrades.length?'No '+(type==='BUY'?'purchases':'sales')+' in this item’s sample history.':'No transactions recorded for this item in the preview.'}</div>`;
  $('moreItemTransactions').hidden=filtered.length<=limit;
  $('moreItemTransactions').onclick=()=>renderItemTransactions(type,limit+5);
}
function renderPriceHistory(range='7d') {
  document.querySelectorAll('[data-history-range]').forEach(button=>{
    const active=button.dataset.historyRange===range;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
    button.onclick=()=>renderPriceHistory(button.dataset.historyRange);
  });
  if(selected.disabled){
    $('priceHistoryChart').innerHTML='<div class="history-empty">No price history for an unavailable item.</div>';
    $('historyReadout').textContent='Trading is disabled for this item.';
    return;
  }
  // Deterministic illustrative series, never represented as real server history.
  const hours={'24h':24,'7d':168,'30d':720}[range];
  const seed=[...selected.id].reduce((sum,c)=>sum+c.charCodeAt(0),0);
  const count=25;
  const now=new Date();
  now.setMinutes(0,0,0);
  const points=Array.from({length:count},(_,index)=>{
    const distance=(count-1-index)/(count-1);
    const movement=1+distance*(Math.sin(index*.72+seed)*.055+Math.cos(index*.33+seed)*.04-.03);
    return {date:new Date(now.getTime()-(count-1-index)/(count-1)*hours*3600000),buy:selected.buy*movement,sell:selected.sell*(movement+distance*.012*Math.sin(index*.51))};
  });
  const w=420,h=202,left=62,right=12,top=15,bottom=27;
  const min=Math.max(0,Math.min(...points.map(p=>p.sell))*.88);
  const max=Math.max(...points.map(p=>p.buy))*1.08;
  const x=index=>left+index/(count-1)*(w-left-right);
  const y=value=>top+(max-value)/(max-min||1)*(h-top-bottom);
  const compact=value=>value>=1000000?'$'+(value/1000000).toFixed(1)+'m':value>=1000?'$'+(value/1000).toFixed(value<10000?1:0)+'k':money(value);
  const dateLabel=date=>range==='24h'?date.toLocaleTimeString('en-US',{hour:'numeric',hour12:true}):date.toLocaleDateString('en-US',{month:'short',day:'numeric'});
  const buyPath=points.map((p,index)=>(index?'L':'M')+x(index).toFixed(2)+','+y(p.buy).toFixed(2)).join(' ');
  const sellPath=points.map((p,index)=>(index?'L':'M')+x(index).toFixed(2)+','+y(p.sell).toFixed(2)).join(' ');
  const floor=h-bottom;
  const grid=Array.from({length:4},(_,i)=>{const value=min+(max-min)*i/3;return `<line x1="${left}" x2="${w-right}" y1="${y(value)}" y2="${y(value)}" class="history-gridline"/><text x="${left-10}" y="${y(value)+3}" text-anchor="end">${compact(value)}</text>`}).join('');
  const labels=[0,8,16,24].map(i=>`<text x="${x(i)}" y="${h-6}" text-anchor="${i===0?'start':i===24?'end':'middle'}">${dateLabel(points[i].date)}</text>`).join('');
  $('priceHistoryChart').innerHTML=`<svg class="history-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Sample buy and sell price history for ${escapeText(selected.name)}, ${range}"><defs><linearGradient id="historyFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8fe0b2" stop-opacity=".16"/><stop offset="100%" stop-color="#8fe0b2" stop-opacity="0"/></linearGradient></defs>${grid}${labels}<path d="${buyPath} L${x(count-1)},${floor} L${left},${floor} Z" fill="url(#historyFill)"/><path d="${buyPath}" class="history-buy-line"/><path d="${sellPath}" class="history-sell-line"/><line id="historyCursor" x1="${x(count-1)}" x2="${x(count-1)}" y1="${top}" y2="${floor}" class="history-cursor"/><circle id="historyBuyDot" cx="${x(count-1)}" cy="${y(points.at(-1).buy)}" r="3.5" class="history-buy-dot"/><circle id="historySellDot" cx="${x(count-1)}" cy="${y(points.at(-1).sell)}" r="3.5" class="history-sell-dot"/></svg><input id="historyPoint" class="history-slider" type="range" min="0" max="24" value="24" aria-label="Explore historical prices">`;
  function showPoint(index){
    const p=points[index];
    $('historyCursor').setAttribute('x1',x(index));$('historyCursor').setAttribute('x2',x(index));
    $('historyBuyDot').setAttribute('cx',x(index));$('historyBuyDot').setAttribute('cy',y(p.buy));
    $('historySellDot').setAttribute('cx',x(index));$('historySellDot').setAttribute('cy',y(p.sell));
    const date=p.date.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
    $('historyReadout').innerHTML=`<span>${date}</span><strong class="history-buy-value">Buy ${money(p.buy)}</strong><strong class="history-sell-value">Sell ${money(p.sell)}</strong>`;
    $('historyPoint').value=index;
    $('historyPoint').setAttribute('aria-valuetext',`${date}, buy ${money(p.buy)}, sell ${money(p.sell)}`);
  }
  $('historyPoint').oninput=event=>showPoint(Number(event.target.value));
  const svg=$('priceHistoryChart').querySelector('svg');
  svg.onpointermove=event=>{
    const bounds=svg.getBoundingClientRect();
    const position=(event.clientX-bounds.left)/bounds.width*w;
    showPoint(Math.max(0,Math.min(count-1,Math.round((position-left)/(w-left-right)*(count-1)))));
  };
  showPoint(count-1);
}
