  function editCategory(cat,creating=false){
    const draft={...cat};if(creating){draft.slot=Array.from({length:54},(_,i)=>i).find(n=>!cats.some(c=>c.slot===n))??-1;draft.name='New category'}
    editor(creating?'Create category':'Edit '+cat.name,cat.id+' · Name, icon, inventory position, and restocking.',`<div class="admin-category-preview" id="categoryIconPreview">${thumb(draft.material)}<span>${esc(draft.name)}</span></div>${input('acName','Display name',draft.name,'required maxlength="60"')}${input('acIcon','Icon material or custom ID',draft.material.toUpperCase(),'required pattern="[A-Za-z0-9_:/.-]+" list="adminMaterials"','For example DIAMOND, GRASS_BLOCK, or a supported custom item ID.')}<div class="admin-form-grid">${input('acSlot','Inventory slot',draft.slot,'type="number" min="-1" max="53" step="1" required','Slots 0–53. Use -1 to hide the category.')}<button type="button" id="hideAdminCategory" class="secondary">Hide category</button></div><div class="admin-slot-picker" aria-label="Category inventory position">${Array.from({length:54},(_,i)=>{const occupied=cats.find(c=>c.slot===i&&c.id!==cat.id);return `<button type="button" data-cat-slot="${i}" class="${i===draft.slot?'selected':''}" ${occupied?'disabled':''} aria-label="Slot ${i}${occupied?', occupied by '+esc(occupied.name):''}">${occupied?thumb(occupied.material):i}</button>`}).join('')}</div><h3 class="admin-form-heading">Automatic restocking</h3>${toggle('acRestock','Restock this category',draft.restock,'Uses the global automatic restock setting.')}<div class="admin-form-grid">${input('acTarget','Target stock',draft.target,'type="number" min="0" step="1" required')}${input('acInterval','Interval (minutes)',draft.interval,'type="number" min="1" step="1" required')}</div><div class="admin-editor-extra"><button class="secondary" id="resetAdminCategory" type="button">Reset to defaults</button>${cat.custom&&!creating?'<button type="button" class="admin-danger" id="deleteAdminCategory">Delete category</button>':''}</div>`,()=>{
      const slot=numeric('acSlot',{min:-1,max:53,integer:true});if(slot>=0&&cats.some(c=>c.id!==cat.id&&c.slot===slot))throw new Error('That inventory slot is already used. Choose an empty slot.');
      const name=$('acName').value.trim();if(!name)throw new Error('Enter a category name.');
      Object.assign(cat,{name,browse:cat.id==='MISC'?'Miscellaneous':name,material:$('acIcon').value.trim().toLowerCase(),slot,restock:$('acRestock').checked,target:numeric('acTarget',{min:0,integer:true}),interval:numeric('acInterval',{min:1,integer:true})});
      log('Category updated',name,`Slot ${slot} · icon ${cat.material} · restock ${cat.restock?cat.target+' every '+cat.interval+'m':'off'}`);closeEditor();refresh();notify('Saved category');
    });
    const updateSlot=()=>document.querySelectorAll('[data-cat-slot]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.catSlot)===Number($('acSlot').value)));
    document.querySelectorAll('[data-cat-slot]').forEach(b=>b.onclick=()=>{$('acSlot').value=b.dataset.catSlot;updateSlot()});$('acSlot').oninput=updateSlot;
    $('hideAdminCategory').onclick=()=>{$('acSlot').value=-1;updateSlot()};
    $('acIcon').oninput=()=>{const value=$('acIcon').value.trim().toLowerCase();$('categoryIconPreview').innerHTML=thumb(value)+'<span>'+esc($('acName').value)+'</span>'};
    $('acName').oninput=()=>{$('categoryIconPreview').lastElementChild.textContent=$('acName').value};
    $('resetAdminCategory').onclick=()=>{const original=defaults.find(c=>c.id===cat.id);$('acName').value=original.name;$('acIcon').value=original.material;$('acSlot').value=original.slot;$('acRestock').checked=original.restock;$('acTarget').value=original.target;$('acInterval').value=original.interval;updateSlot();$('acIcon').oninput()};
    if($('deleteAdminCategory'))$('deleteAdminCategory').onclick=()=>confirmAction('Delete '+cat.name+'?','Its items will move to Miscellaneous and this custom category slot will become available again.',()=>{for(const i of items.filter(i=>i.adminCategory===cat.id))i.adminCategory='MISC';log('Category deleted',cat.name,'Items moved to Miscellaneous');Object.assign(cat,defaults.find(c=>c.id===cat.id),{slot:-1});state.cat=null});
  }
